{"implementation":"def solve(case):
    nodes = list(case.get("nodes", []))
    required_symbols = set(case.get("required_symbols", []))

    by_id = {}
    children = {}
    order = []
    for node in nodes:
        node_id = node.get("id")
        by_id[node_id] = node
        order.append(node_id)
        children.setdefault(node_id, [])
        parent = node.get("parent")
        if parent is not None:
            children.setdefault(parent, []).append(node_id)

    retained = set()

    def mark_with_ancestors(node_id):
        while node_id is not None and node_id not in retained:
            retained.add(node_id)
            node = by_id.get(node_id)
            if node is None:
                break
            node_id = node.get("parent")

    for node in nodes:
        if not node.get("removable", False) or node.get("symbol") in required_symbols:
            mark_with_ancestors(node.get("id"))

    removed = []
    retained_list = []
    for node_id in order:
        if node_id in retained:
            retained_list.append(str(node_id))
        else:
            removed.append(str(node_id))

    return {
        "removed_node_ids": removed,
        "retained_node_ids": retained_list,
    }
"}
